/**
 * Output file naming (instruction §12.4). The source is never overwritten, and
 * unsafe path characters never reach a download.
 */

export type NamingPattern = 'converted-to' | 'target-suffix' | 'dated';

export interface NamingOptions {
  pattern: NamingPattern;
  /** Overrides the pattern entirely when the user types a name. */
  custom?: string;
}

const UNSAFE = /[�-<>:"/\\|?*]/g;
// Reserved on Windows even with an extension; a download named CON.dxf fails.
const RESERVED = /^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i;

export function sanitizeFileName(name: string, fallback = 'output'): string {
  let safe = name.replace(UNSAFE, '_').replace(/\s+/g, ' ').trim();
  safe = safe.replace(/^\.+/, '').replace(/[. ]+$/, '');
  if (!safe) safe = fallback;
  if (RESERVED.test(safe)) safe = `_${safe}`;
  return safe.slice(0, 180);
}

export function baseName(fileName: string): string {
  const withoutPath = fileName.split(/[\\/]/).pop() ?? fileName;
  const dot = withoutPath.lastIndexOf('.');
  return dot > 0 ? withoutPath.slice(0, dot) : withoutPath;
}

export function extensionOf(fileName: string): string {
  const withoutPath = fileName.split(/[\\/]/).pop() ?? fileName;
  const dot = withoutPath.lastIndexOf('.');
  return dot > 0 ? withoutPath.slice(dot + 1).toLowerCase() : '';
}

function isoDate(now = new Date()): string {
  return now.toISOString().slice(0, 10).replace(/-/g, '');
}

export function buildOutputName(
  sourceFileName: string,
  targetFormatId: string,
  targetExtension: string,
  options: NamingOptions = { pattern: 'converted-to' },
  now = new Date()
): string {
  if (options.custom) return sanitizeFileName(ensureExtension(options.custom, targetExtension));
  const base = sanitizeFileName(baseName(sourceFileName));
  const slug = targetFormatId.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
  switch (options.pattern) {
    case 'target-suffix':
      return sanitizeFileName(`${base}_${slug}.${targetExtension}`);
    case 'dated':
      return sanitizeFileName(`${base}_${isoDate(now)}_${slug}.${targetExtension}`);
    case 'converted-to':
    default:
      return sanitizeFileName(`${base}_converted_to_${slug}.${targetExtension}`);
  }
}

function ensureExtension(name: string, extension: string): string {
  return extensionOf(name) === extension.toLowerCase() ? name : `${name}.${extension}`;
}

/**
 * Makes a name unique inside an already-used set by appending _2, _3, ... so a
 * batch containing two `site.dxf` files from different folders cannot clobber
 * one output with the other.
 */
export function uniqueName(name: string, used: Set<string>): string {
  if (!used.has(name)) {
    used.add(name);
    return name;
  }
  const dot = name.lastIndexOf('.');
  const stem = dot > 0 ? name.slice(0, dot) : name;
  const extension = dot > 0 ? name.slice(dot) : '';
  for (let index = 2; index < 10000; index++) {
    const candidate = `${stem}_${index}${extension}`;
    if (!used.has(candidate)) {
      used.add(candidate);
      return candidate;
    }
  }
  const fallback = `${stem}_${Date.now()}${extension}`;
  used.add(fallback);
  return fallback;
}
